using Microsoft.Data.Sqlite;
using NeoPlayer.Windows.Models;
using System.Text.Json;

namespace NeoPlayer.Windows.Data;

public sealed partial class NeoDatabase : IAsyncDisposable
{
    SqliteConnection? _connection;
    readonly SemaphoreSlim _gate=new(1,1);
    SqliteConnection Conn => _connection ?? throw new InvalidOperationException("Database not initialized");
    public async Task InitializeAsync()
    {
        AppPaths.Ensure();
        _connection=new SqliteConnection($"Data Source={AppPaths.Database};Cache=Shared;Mode=ReadWriteCreate");
        await _connection.OpenAsync();
        using(var pragma=Conn.CreateCommand()){pragma.CommandText="PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; PRAGMA synchronous=NORMAL;"; await pragma.ExecuteNonQueryAsync();}
        var sql=@"
CREATE TABLE IF NOT EXISTS songs(id INTEGER PRIMARY KEY,path TEXT NOT NULL UNIQUE,title TEXT NOT NULL,artist TEXT NOT NULL,album TEXT NOT NULL,albumArtist TEXT NOT NULL,genre TEXT NOT NULL,year INTEGER NOT NULL,durationMs INTEGER NOT NULL,trackNumber INTEGER NOT NULL,discNumber INTEGER NOT NULL,composer TEXT NOT NULL,bitrate INTEGER NOT NULL,mimeType TEXT NOT NULL,sizeBytes INTEGER NOT NULL,relativePath TEXT NOT NULL,dateAdded INTEGER NOT NULL,dateModified INTEGER NOT NULL,customArtworkPath TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_songs_album ON songs(album); CREATE INDEX IF NOT EXISTS idx_songs_artist ON songs(artist); CREATE INDEX IF NOT EXISTS idx_songs_date ON songs(dateAdded);
CREATE TABLE IF NOT EXISTS favorites(songId INTEGER PRIMARY KEY,addedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS playlists(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',artworkPath TEXT,createdAt INTEGER NOT NULL,folderId INTEGER,customOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS playlist_songs(playlistId INTEGER NOT NULL,songId INTEGER NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(playlistId,songId),FOREIGN KEY(playlistId) REFERENCES playlists(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS playlist_folders(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,parentId INTEGER,position INTEGER NOT NULL DEFAULT 0,createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS playlist_preferences(playlistId INTEGER PRIMARY KEY,sortMode TEXT NOT NULL DEFAULT 'custom',ascending INTEGER NOT NULL DEFAULT 1,viewMode TEXT NOT NULL DEFAULT 'list');
CREATE TABLE IF NOT EXISTS pinned_collections(type TEXT NOT NULL,key TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,pinnedAt INTEGER NOT NULL,PRIMARY KEY(type,key));
CREATE TABLE IF NOT EXISTS hidden_songs(songId INTEGER NOT NULL,scopeType TEXT NOT NULL DEFAULT 'global',scopeKey TEXT NOT NULL DEFAULT '',hiddenAt INTEGER NOT NULL,PRIMARY KEY(songId,scopeType,scopeKey));
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',artworkPath TEXT,createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS category_songs(categoryId INTEGER NOT NULL,songId INTEGER NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(categoryId,songId),FOREIGN KEY(categoryId) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS listening_history(songId INTEGER PRIMARY KEY,playCount INTEGER NOT NULL DEFAULT 0,skipCount INTEGER NOT NULL DEFAULT 0,totalListeningMs INTEGER NOT NULL DEFAULT 0,lastPlayedAt INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS lyrics(songId INTEGER PRIMARY KEY,original TEXT NOT NULL,translation TEXT NOT NULL DEFAULT '',romanization TEXT NOT NULL DEFAULT '',synchronized INTEGER NOT NULL DEFAULT 0,source TEXT NOT NULL DEFAULT 'local',updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS metadata_overrides(songId INTEGER PRIMARY KEY,title TEXT NOT NULL,artist TEXT NOT NULL,album TEXT NOT NULL,genre TEXT NOT NULL,year INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS favorite_collections(type TEXT NOT NULL,key TEXT NOT NULL,addedAt INTEGER NOT NULL,PRIMARY KEY(type,key));
CREATE TABLE IF NOT EXISTS track_audio_effects(songId INTEGER PRIMARY KEY,preset TEXT NOT NULL DEFAULT 'Normal',bass REAL NOT NULL DEFAULT 0,virtualizer REAL NOT NULL DEFAULT 0,loudnessDb REAL NOT NULL DEFAULT 0,bandLevels TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS audio_analysis(songId INTEGER PRIMARY KEY,integratedLufs REAL NOT NULL DEFAULT -14,peakDb REAL NOT NULL DEFAULT 0,bpm REAL NOT NULL DEFAULT 0,gainMb INTEGER NOT NULL DEFAULT 0,analyzedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS advanced_audio_analysis(songId INTEGER PRIMARY KEY,bpm REAL NOT NULL DEFAULT 0,beatIntervalMs REAL NOT NULL DEFAULT 0,beatOffsetMs REAL NOT NULL DEFAULT 0,beatConfidence REAL NOT NULL DEFAULT 0,phraseLengthBeats INTEGER NOT NULL DEFAULT 16,phraseOffsetMs REAL NOT NULL DEFAULT 0,phraseConfidence REAL NOT NULL DEFAULT 0,musicalKey TEXT NOT NULL DEFAULT '',camelotKey TEXT NOT NULL DEFAULT '',keyConfidence REAL NOT NULL DEFAULT 0,energy REAL NOT NULL DEFAULT 0,valence REAL NOT NULL DEFAULT .5,danceability REAL NOT NULL DEFAULT 0,spectralCentroidHz REAL NOT NULL DEFAULT 0,dynamicRangeDb REAL NOT NULL DEFAULT 0,mood TEXT NOT NULL DEFAULT 'unknown',beatGridJson TEXT NOT NULL DEFAULT '[]',analyzedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS replay_gain_cache(songId INTEGER PRIMARY KEY,trackGainDb REAL,albumGainDb REAL,trackPeak REAL,r128TrackGainDb REAL,source TEXT NOT NULL DEFAULT 'none',scannedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS track_visual_profiles(songId INTEGER PRIMARY KEY,canvasPath TEXT,canvasEnabled INTEGER NOT NULL DEFAULT 0,canvasFit TEXT NOT NULL DEFAULT 'crop',canvasStartMs INTEGER NOT NULL DEFAULT 0,canvasEndMs INTEGER NOT NULL DEFAULT 0,canvasPlaybackSpeed REAL NOT NULL DEFAULT 1,themeMode TEXT NOT NULL DEFAULT 'inherit',accentArgb INTEGER NOT NULL DEFAULT 0,backgroundArgb INTEGER NOT NULL DEFAULT 0,secondaryArgb INTEGER NOT NULL DEFAULT 0,visualizerMode TEXT NOT NULL DEFAULT 'waveform',visualizerSensitivity REAL NOT NULL DEFAULT 1,animationIntensity REAL NOT NULL DEFAULT 1,backgroundImagePath TEXT NOT NULL DEFAULT '',backgroundMode TEXT NOT NULL DEFAULT 'overlay',backgroundOpacity REAL NOT NULL DEFAULT .28,backgroundBlurDp INTEGER NOT NULL DEFAULT 18,updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS offline_lyrics_transcripts(songId INTEGER PRIMARY KEY,engine TEXT NOT NULL DEFAULT 'vosk',modelId TEXT NOT NULL,language TEXT NOT NULL,plainText TEXT NOT NULL,lrcText TEXT NOT NULL,wordTimedJson TEXT NOT NULL DEFAULT '[]',averageConfidence REAL NOT NULL DEFAULT 0,generatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS offline_speech_models(id TEXT PRIMARY KEY,displayName TEXT NOT NULL,language TEXT NOT NULL,localPath TEXT NOT NULL,sampleRate INTEGER NOT NULL DEFAULT 16000,importedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS recommendation_feedback(songId INTEGER PRIMARY KEY,boost INTEGER NOT NULL DEFAULT 0,dismissCount INTEGER NOT NULL DEFAULT 0,lastSeededAt INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS track_experience_preferences(id INTEGER PRIMARY KEY CHECK(id=0),selectedSpeechModelId TEXT NOT NULL DEFAULT '',selectedSpeechLanguage TEXT NOT NULL DEFAULT 'en');
CREATE TABLE IF NOT EXISTS offline_backup_entries(songId INTEGER PRIMARY KEY,position INTEGER NOT NULL,score REAL NOT NULL,reason TEXT NOT NULL,mood TEXT NOT NULL DEFAULT 'unknown',genre TEXT NOT NULL DEFAULT '',generatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS queue_state(position INTEGER PRIMARY KEY,songId INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_state(key TEXT PRIMARY KEY,value TEXT NOT NULL);
";
        using var cmd=Conn.CreateCommand(); cmd.CommandText=sql; await cmd.ExecuteNonQueryAsync();
    }
    static long Now()=>DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
    async Task<long> InsertAndGetIdAsync(string sql, params (string,object?)[] args)
    {
        await _gate.WaitAsync();
        try
        {
            using var c=Conn.CreateCommand(); c.CommandText=sql;
            foreach(var(a,v) in args)c.Parameters.AddWithValue(a,v??DBNull.Value);
            var result=await c.ExecuteScalarAsync();
            return result is null or DBNull ? 0L : Convert.ToInt64(result);
        }
        finally{_gate.Release();}
    }
    async Task ExecuteAsync(string sql, params (string,object?)[] args){await _gate.WaitAsync();try{using var c=Conn.CreateCommand();c.CommandText=sql;foreach(var(a,v)in args)c.Parameters.AddWithValue(a,v??DBNull.Value);await c.ExecuteNonQueryAsync();}finally{_gate.Release();}}
    async Task<T?> ScalarAsync<T>(string sql, params (string,object?)[] args){await _gate.WaitAsync();try{using var c=Conn.CreateCommand();c.CommandText=sql;foreach(var(a,v)in args)c.Parameters.AddWithValue(a,v??DBNull.Value);var scalar=await c.ExecuteScalarAsync(); if(scalar is null||scalar is DBNull)return default; return (T)Convert.ChangeType(scalar,typeof(T));}finally{_gate.Release();}}
    async Task<List<T>> QueryAsync<T>(string sql,Func<SqliteDataReader,T> map,params (string,object?)[] args){await _gate.WaitAsync();try{using var c=Conn.CreateCommand();c.CommandText=sql;foreach(var(a,v)in args)c.Parameters.AddWithValue(a,v??DBNull.Value);using var r=await c.ExecuteReaderAsync();var list=new List<T>();while(await r.ReadAsync())list.Add(map(r));return list;}finally{_gate.Release();}}
    static Song ReadSong(SqliteDataReader r)=>new(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetInt32(7),r.GetInt64(8),r.GetInt32(9),r.GetInt32(10),r.GetString(11),r.GetInt32(12),r.GetString(13),r.GetInt64(14),r.GetString(15),r.GetInt64(16),r.GetInt64(17),r.GetString(18));
    const string SongCols="id,path,title,artist,album,albumArtist,genre,year,durationMs,trackNumber,discNumber,composer,bitrate,mimeType,sizeBytes,relativePath,dateAdded,dateModified,customArtworkPath";
    public async Task<List<Song>> GetSongsAsync(bool includeHidden=false)
    {
        var songs=await QueryAsync($"SELECT {SongCols} FROM songs s WHERE @hidden=1 OR NOT EXISTS(SELECT 1 FROM hidden_songs h WHERE h.songId=s.id AND h.scopeType='global') ORDER BY title COLLATE NOCASE",ReadSong,("@hidden",includeHidden?1:0));
        return await ApplyOverridesAsync(songs);
    }
    public async Task<Song?> GetSongAsync(long id)
    {
        var song=(await QueryAsync($"SELECT {SongCols} FROM songs WHERE id=@id",ReadSong,("@id",id))).FirstOrDefault();
        if(song is null)return null;
        return (await ApplyOverridesAsync(new[]{song})).First();
    }
    public async Task UpsertSongsAsync(IEnumerable<Song> songs)
    {
        await _gate.WaitAsync(); try{using var tx=Conn.BeginTransaction(); foreach(var s in songs){using var c=Conn.CreateCommand();c.Transaction=tx;c.CommandText=@"INSERT INTO songs(id,path,title,artist,album,albumArtist,genre,year,durationMs,trackNumber,discNumber,composer,bitrate,mimeType,sizeBytes,relativePath,dateAdded,dateModified,customArtworkPath) VALUES(@id,@p,@t,@ar,@al,@aa,@g,@y,@d,@tn,@dn,@co,@b,@m,@sz,@rp,@da,@dm,@ca) ON CONFLICT(id) DO UPDATE SET path=excluded.path,title=excluded.title,artist=excluded.artist,album=excluded.album,albumArtist=excluded.albumArtist,genre=excluded.genre,year=excluded.year,durationMs=excluded.durationMs,trackNumber=excluded.trackNumber,discNumber=excluded.discNumber,composer=excluded.composer,bitrate=excluded.bitrate,mimeType=excluded.mimeType,sizeBytes=excluded.sizeBytes,relativePath=excluded.relativePath,dateModified=excluded.dateModified";
            object?[] v={s.Id,s.Path,s.Title,s.Artist,s.Album,s.AlbumArtist,s.Genre,s.Year,s.DurationMs,s.TrackNumber,s.DiscNumber,s.Composer,s.Bitrate,s.MimeType,s.SizeBytes,s.RelativePath,s.DateAdded,s.DateModified,s.CustomArtworkPath}; string[] n={"@id","@p","@t","@ar","@al","@aa","@g","@y","@d","@tn","@dn","@co","@b","@m","@sz","@rp","@da","@dm","@ca"};for(int i=0;i<n.Length;i++)c.Parameters.AddWithValue(n[i],v[i]??DBNull.Value); await c.ExecuteNonQueryAsync();} tx.Commit();}finally{_gate.Release();}
    }
    public async Task DeleteMissingSongsAsync(HashSet<long> present){var all=await QueryAsync("SELECT id FROM songs",r=>r.GetInt64(0));var missing=all.Where(x=>!present.Contains(x)).ToList(); foreach(var chunk in missing.Chunk(250)){var ids=string.Join(',',chunk);await ExecuteAsync($"DELETE FROM songs WHERE id IN ({ids})");}}
    public Task SetFavoriteAsync(long id,bool value)=>value?ExecuteAsync("INSERT OR REPLACE INTO favorites(songId,addedAt) VALUES(@id,@n)",("@id",id),("@n",Now())):ExecuteAsync("DELETE FROM favorites WHERE songId=@id",("@id",id));
    public Task<HashSet<long>> GetFavoriteIdsAsync()=>QueryAsync("SELECT songId FROM favorites",r=>r.GetInt64(0)).ContinueWith(t=>t.Result.ToHashSet());
    public Task<List<ListeningHistory>> GetHistoryAsync()=>QueryAsync("SELECT songId,playCount,skipCount,totalListeningMs,lastPlayedAt FROM listening_history",r=>new ListeningHistory(r.GetInt64(0),r.GetInt32(1),r.GetInt32(2),r.GetInt64(3),r.GetInt64(4)));
    public Task RecordListenAsync(long id,long listenedMs,bool completed,bool skipped)=>ExecuteAsync(@"INSERT INTO listening_history(songId,playCount,skipCount,totalListeningMs,lastPlayedAt) VALUES(@id,@pc,@sc,@ms,@n) ON CONFLICT(songId) DO UPDATE SET playCount=playCount+@pc,skipCount=skipCount+@sc,totalListeningMs=totalListeningMs+@ms,lastPlayedAt=@n",("@id",id),("@pc",completed?1:0),("@sc",skipped?1:0),("@ms",Math.Max(0,listenedMs)),("@n",Now()));
    public Task<List<Playlist>> GetPlaylistsAsync()=>QueryAsync("SELECT id,title,description,artworkPath,createdAt,folderId,customOrder FROM playlists ORDER BY customOrder,title COLLATE NOCASE",r=>new Playlist(r.GetInt64(0),r.GetString(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.GetInt64(4),r.IsDBNull(5)?null:r.GetInt64(5),r.GetInt32(6)));
    public Task<long> CreatePlaylistAsync(string title,long? folderId=null)=>InsertAndGetIdAsync("INSERT INTO playlists(title,createdAt,folderId,customOrder) VALUES(@t,@n,@f,COALESCE((SELECT MAX(customOrder)+1 FROM playlists),0)); SELECT last_insert_rowid();",("@t",title.Trim()),("@n",Now()),("@f",folderId));
    public Task RenamePlaylistAsync(long id,string title)=>ExecuteAsync("UPDATE playlists SET title=@t WHERE id=@id",("@t",title),("@id",id));
    public Task DeletePlaylistAsync(long id)=>ExecuteAsync("DELETE FROM playlists WHERE id=@id",("@id",id));
    public Task MovePlaylistAsync(long id,long? folderId)=>ExecuteAsync("UPDATE playlists SET folderId=@f WHERE id=@id",("@f",folderId),("@id",id));
    public async Task<List<Song>> GetPlaylistSongsAsync(long id)
    {
        var songs=await QueryAsync($"SELECT {string.Join(',',SongCols.Split(',').Select(x=>"s."+x))} FROM playlist_songs ps JOIN songs s ON s.id=ps.songId WHERE ps.playlistId=@id AND NOT EXISTS(SELECT 1 FROM hidden_songs h WHERE h.songId=s.id AND h.scopeType='global') ORDER BY ps.position",ReadSong,("@id",id));
        return await ApplyOverridesAsync(songs);
    }
    public Task AddToPlaylistAsync(long playlistId,long songId)=>ExecuteAsync("INSERT OR IGNORE INTO playlist_songs(playlistId,songId,position) VALUES(@p,@s,COALESCE((SELECT MAX(position)+1 FROM playlist_songs WHERE playlistId=@p),0))",("@p",playlistId),("@s",songId));
    public Task RemoveFromPlaylistAsync(long playlistId,long songId)=>ExecuteAsync("DELETE FROM playlist_songs WHERE playlistId=@p AND songId=@s",("@p",playlistId),("@s",songId));
    public async Task ReorderPlaylistAsync(long playlistId,IReadOnlyList<long> ids){await _gate.WaitAsync();try{using var tx=Conn.BeginTransaction();for(int i=0;i<ids.Count;i++){using var c=Conn.CreateCommand();c.Transaction=tx;c.CommandText="UPDATE playlist_songs SET position=@i WHERE playlistId=@p AND songId=@s";c.Parameters.AddWithValue("@i",i);c.Parameters.AddWithValue("@p",playlistId);c.Parameters.AddWithValue("@s",ids[i]);await c.ExecuteNonQueryAsync();}tx.Commit();}finally{_gate.Release();}}
    public Task<List<PlaylistFolder>> GetPlaylistFoldersAsync()=>QueryAsync("SELECT id,title,parentId,position,createdAt FROM playlist_folders ORDER BY position,title COLLATE NOCASE",r=>new PlaylistFolder(r.GetInt64(0),r.GetString(1),r.IsDBNull(2)?null:r.GetInt64(2),r.GetInt32(3),r.GetInt64(4)));
    public async Task<long> CreateFolderAsync(string title,long? parentId=null){if(parentId is not null && !await IsValidFolderParentAsync(0,parentId))throw new InvalidOperationException("Invalid folder parent");return await InsertAndGetIdAsync("INSERT INTO playlist_folders(title,parentId,position,createdAt) VALUES(@t,@p,COALESCE((SELECT MAX(position)+1 FROM playlist_folders WHERE parentId IS @p),0),@n); SELECT last_insert_rowid();",("@t",title.Trim()),("@p",parentId),("@n",Now()));}
    public async Task<bool> IsValidFolderParentAsync(long folderId,long? candidate){if(candidate is null)return true;if(candidate==folderId&&folderId!=0)return false;var folders=await GetPlaylistFoldersAsync();var map=folders.ToDictionary(x=>x.Id,x=>x.ParentId);var cur=candidate;while(cur is not null){if(cur==folderId&&folderId!=0)return false;cur=map.GetValueOrDefault(cur.Value);}return true;}
    public async Task MoveFolderAsync(long id,long? parent){if(!await IsValidFolderParentAsync(id,parent))throw new InvalidOperationException("Folder cycle");await ExecuteAsync("UPDATE playlist_folders SET parentId=@p WHERE id=@id",("@p",parent),("@id",id));}
    public Task DeleteFolderAsync(long id)=>ExecuteAsync("UPDATE playlists SET folderId=NULL WHERE folderId=@id; UPDATE playlist_folders SET parentId=NULL WHERE parentId=@id; DELETE FROM playlist_folders WHERE id=@id",("@id",id));
    public Task<List<Category>> GetCategoriesAsync()=>QueryAsync("SELECT id,title,description,artworkPath,createdAt FROM categories ORDER BY title COLLATE NOCASE",r=>new Category(r.GetInt64(0),r.GetString(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.GetInt64(4)));
    public Task<long> CreateCategoryAsync(string title)=>InsertAndGetIdAsync("INSERT INTO categories(title,createdAt) VALUES(@t,@n); SELECT last_insert_rowid();",("@t",title.Trim()),("@n",Now()));
    public Task AddToCategoryAsync(long categoryId,long songId)=>ExecuteAsync("INSERT OR IGNORE INTO category_songs(categoryId,songId,position) VALUES(@c,@s,COALESCE((SELECT MAX(position)+1 FROM category_songs WHERE categoryId=@c),0))",("@c",categoryId),("@s",songId));
    public async Task<List<Song>> GetCategorySongsAsync(long id)
    {
        var songs=await QueryAsync($"SELECT {string.Join(',',SongCols.Split(',').Select(x=>"s."+x))} FROM category_songs cs JOIN songs s ON s.id=cs.songId WHERE cs.categoryId=@id AND NOT EXISTS(SELECT 1 FROM hidden_songs h WHERE h.songId=s.id AND h.scopeType='global') ORDER BY cs.position",ReadSong,("@id",id));
        return await ApplyOverridesAsync(songs);
    }
    public Task SetHiddenAsync(long songId,bool hidden,string scopeType="global",string scopeKey="")=>hidden?ExecuteAsync("INSERT OR REPLACE INTO hidden_songs(songId,scopeType,scopeKey,hiddenAt) VALUES(@s,@t,@k,@n)",("@s",songId),("@t",scopeType),("@k",scopeKey),("@n",Now())):ExecuteAsync("DELETE FROM hidden_songs WHERE songId=@s AND scopeType=@t AND scopeKey=@k",("@s",songId),("@t",scopeType),("@k",scopeKey));
    public Task<(string SortMode,bool Ascending,string ViewMode)> GetPlaylistPreferenceAsync(long id)=>QueryAsync("SELECT sortMode,ascending,viewMode FROM playlist_preferences WHERE playlistId=@id",r=>(r.GetString(0),r.GetInt32(1)!=0,r.GetString(2)),("@id",id)).ContinueWith(t=>t.Result.FirstOrDefault()==default?("custom",true,"list"):t.Result.First());
    public Task SavePlaylistPreferenceAsync(long id,string sort,bool asc,string view)=>ExecuteAsync("INSERT OR REPLACE INTO playlist_preferences(playlistId,sortMode,ascending,viewMode) VALUES(@id,@s,@a,@v)",("@id",id),("@s",sort),("@a",asc?1:0),("@v",view));
    public Task<List<long>> GetHiddenSongIdsAsync()=>QueryAsync("SELECT songId FROM hidden_songs WHERE scopeType='global'",r=>r.GetInt64(0));
    public Task SetPinnedAsync(string type,string key,bool pinned)=>pinned?ExecuteAsync("INSERT OR REPLACE INTO pinned_collections(type,key,position,pinnedAt) VALUES(@t,@k,COALESCE((SELECT MAX(position)+1 FROM pinned_collections),0),@n)",("@t",type),("@k",key),("@n",Now())):ExecuteAsync("DELETE FROM pinned_collections WHERE type=@t AND key=@k",("@t",type),("@k",key));
    public Task SetFavoriteCollectionAsync(string type,string key,bool value)=>value?ExecuteAsync("INSERT OR REPLACE INTO favorite_collections(type,key,addedAt) VALUES(@t,@k,@n)",("@t",type),("@k",key),("@n",Now())):ExecuteAsync("DELETE FROM favorite_collections WHERE type=@t AND key=@k",("@t",type),("@k",key));
    public Task<List<(string Type,string Key,int Position)>> GetPinsAsync()=>QueryAsync("SELECT type,key,position FROM pinned_collections ORDER BY position",r=>(r.GetString(0),r.GetString(1),r.GetInt32(2)));
    public Task SetMetadataOverrideAsync(long id,string title,string artist,string album,string genre,int year)=>ExecuteAsync("INSERT OR REPLACE INTO metadata_overrides(songId,title,artist,album,genre,year) VALUES(@id,@t,@ar,@al,@g,@y)",("@id",id),("@t",title),("@ar",artist),("@al",album),("@g",genre),("@y",year));
    public Task ClearMetadataOverrideAsync(long id)=>ExecuteAsync("DELETE FROM metadata_overrides WHERE songId=@id",("@id",id));
    public Task<Dictionary<long,(string Title,string Artist,string Album,string Genre,int Year)>> GetMetadataOverridesAsync()=>QueryAsync("SELECT songId,title,artist,album,genre,year FROM metadata_overrides",r=>(Id:r.GetInt64(0),V:(r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetInt32(5)))).ContinueWith(t=>t.Result.ToDictionary(x=>x.Id,x=>x.V));
    async Task<List<Song>> ApplyOverridesAsync(IEnumerable<Song> source)
    {
        var list=source.ToList(); if(list.Count==0)return list;
        var map=await GetMetadataOverridesAsync();
        for(var i=0;i<list.Count;i++)if(map.TryGetValue(list[i].Id,out var v))list[i]=list[i] with{Title=v.Title,Artist=v.Artist,Album=v.Album,Genre=v.Genre,Year=v.Year};
        return list;
    }
