    public Task SaveTrackVisualAsync(TrackVisualProfile v)=>ExecuteAsync(@"INSERT OR REPLACE INTO track_visual_profiles(songId,canvasPath,canvasEnabled,canvasFit,canvasStartMs,canvasEndMs,canvasPlaybackSpeed,themeMode,accentArgb,backgroundArgb,secondaryArgb,visualizerMode,visualizerSensitivity,animationIntensity,backgroundImagePath,backgroundMode,backgroundOpacity,backgroundBlurDp,updatedAt) VALUES(@id,@c,@ce,@cf,@cs,@ee,@sp,@tm,@a,@b,@s,@vm,@vs,@ai,@bg,@bm,@bo,@bb,@n)",("@id",v.SongId),("@c",v.CanvasPath),("@ce",v.CanvasEnabled?1:0),("@cf",v.CanvasFit),("@cs",v.CanvasStartMs),("@ee",v.CanvasEndMs),("@sp",v.CanvasPlaybackSpeed),("@tm",v.ThemeMode),("@a",v.AccentArgb),("@b",v.BackgroundArgb),("@s",v.SecondaryArgb),("@vm",v.VisualizerMode),("@vs",v.VisualizerSensitivity),("@ai",v.AnimationIntensity),("@bg",v.BackgroundImagePath),("@bm",v.BackgroundMode),("@bo",v.BackgroundOpacity),("@bb",v.BackgroundBlurDp),("@n",Now()));
