    public async Task SaveOfflineBackupEntriesAsync(IEnumerable<OfflineBackupEntry> entries){await _gate.WaitAsync();try{using var tx=Conn.BeginTransaction();using(var d=Conn.CreateCommand()){d.Transaction=tx;d.CommandText="DELETE FROM offline_backup_entries";await d.ExecuteNonQueryAsync();}foreach(var e in entries){using var c=Conn.CreateCommand();c.Transaction=tx;c.CommandText="INSERT INTO offline_backup_entries(songId,position,score,reason,mood,genre,generatedAt) VALUES(@s,@p,@sc,@r,@m,@g,@n)";c.Parameters.AddWithValue("@s",e.SongId);c.Parameters.AddWithValue("@p",e.Position);c.Parameters.AddWithValue("@sc",e.Score);c.Parameters.AddWithValue("@r",e.Reason);c.Parameters.AddWithValue("@m",e.Mood);c.Parameters.AddWithValue("@g",e.Genre);c.Parameters.AddWithValue("@n",e.GeneratedAt);await c.ExecuteNonQueryAsync();}tx.Commit();}finally{_gate.Release();}}
    public Task<List<OfflineBackupEntry>> GetOfflineBackupEntriesAsync()=>QueryAsync("SELECT songId,position,score,reason,mood,genre,generatedAt FROM offline_backup_entries ORDER BY position",r=>new OfflineBackupEntry(r.GetInt64(0),r.GetInt32(1),r.GetFloat(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetInt64(6)));
