    public Task<List<RecommendationFeedback>> GetFeedbackAsync()=>QueryAsync("SELECT songId,boost,dismissCount,lastSeededAt FROM recommendation_feedback",r=>new RecommendationFeedback(r.GetInt64(0),r.GetInt32(1),r.GetInt32(2),r.GetInt64(3)));
