    public Task SaveQueueAsync(IEnumerable<long> ids)=>ExecuteQueueAsync(ids);
    async Task ExecuteQueueAsync(IEnumerable<long> ids){await _gate.WaitAsync();try{using var tx=Conn.BeginTransaction();using(var d=Conn.CreateCommand()){d.Transaction=tx;d.CommandText="DELETE FROM queue_state";await d.ExecuteNonQueryAsync();}int i=0;foreach(var id in ids){using var c=Conn.CreateCommand();c.Transaction=tx;c.CommandText="INSERT INTO queue_state(position,songId) VALUES(@p,@s)";c.Parameters.AddWithValue("@p",i++);c.Parameters.AddWithValue("@s",id);await c.ExecuteNonQueryAsync();}tx.Commit();}finally{_gate.Release();}}
    public Task<List<long>> LoadQueueAsync()=>QueryAsync("SELECT songId FROM queue_state ORDER BY position",r=>r.GetInt64(0));
    public Task SetAppStateAsync(string key,string value)=>ExecuteAsync("INSERT OR REPLACE INTO app_state(key,value) VALUES(@k,@v)",("@k",key),("@v",value));
    public Task<string?> GetAppStateAsync(string key)=>ScalarAsync<string>("SELECT value FROM app_state WHERE key=@k",("@k",key));
    public async Task ExportSnapshotAsync(string destination){await _gate.WaitAsync();try{if(File.Exists(destination))File.Delete(destination);await using var target=new SqliteConnection($"Data Source={destination};Mode=ReadWriteCreate");await target.OpenAsync();Conn.BackupDatabase(target);}finally{_gate.Release();}}
    public async Task ImportSnapshotAsync(string source){await _gate.WaitAsync();try{await using var src=new SqliteConnection($"Data Source={source};Mode=ReadOnly");await src.OpenAsync();src.BackupDatabase(Conn);}finally{_gate.Release();}}
    public string DatabasePath=>AppPaths.Database;
    public async ValueTask DisposeAsync(){if(_connection is not null){await _connection.DisposeAsync();_connection=null;}_gate.Dispose();}
}
